import React from 'react';
import Header from './components/Header';
import styled from 'styled-components';

const MainContent = styled.main`
  padding: 20px;
  max-width: 1200px;
  margin: 0 auto;
`;

const Footer = styled.footer`
  background: #333;
  color: white;
  text-align: center;
  padding: 20px;
  position: relative;
  bottom: 0;
  width: 100%;
`;

function App() {
  return (
    <div className="App">
      <Header />
      <MainContent>
        <h1>Welcome to Nike Store</h1>
        <p>Your one-stop shop for the latest Nike products.</p>
      </MainContent>
      <Footer>
        <p>&copy; 2023 Nike Store. All rights reserved.</p>
      </Footer>
    </div>
  );
}

export default App;
